import React, { useState, useEffect } from 'react';
import axios from 'axios';
import jsPDF from 'jspdf';

export default function AiPdf() {
  const [chatMessages, setChatMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [aiData, setAiData] = useState(null);

  // Function to fetch AI data based on user input
  const handleSend = async () => {
    if (inputValue.trim() === '') return;

    try {
      const response = await axios.post('/api/ai-response', { message: inputValue });
      setAiData(response.data);
      setChatMessages([...chatMessages, { type: 'user', content: inputValue }]);
      setInputValue('');
    } catch (error) {
      console.error('Error fetching AI data:', error);
    }
  };

  // Function to generate PDF based on chat history
  const generatePdf = () => {
    if (!chatMessages.length) return;

    const doc = new jsPDF();
    let yPosition = 20;

    chatMessages.forEach((message, index) => {
      if (index === 0 && message.type === 'user') {
        doc.text('AI Chat History', 10, yPosition);
        yPosition += 30;
      }

      const textToPrint = `${message.type}: ${message.content}`;
      doc.text(textToPrint, 10, yPosition);
      yPosition += 20;
    });

    doc.save('chat_history.pdf');
  };

  // Fetch AI data based on user input
  useEffect(() => {
    if (inputValue.trim() !== '') return;

    axios.get('/api/ai-analysis')
      .then(response => setAiData(response.data))
      .catch(error => console.error('Error fetching AI data:', error));
  }, [inputValue]);

  return (
    <div>
      <h1>AI Chat PDF Created</h1>
      {chatMessages.length > 0 && (
        <>
          <h2>Chat History</h2>
          {chatMessages.map((message, index) => (
            <p key={index}>{`${message.type}: ${message.content}`}</p>
          ))}
        </>
      )}
      <input
        type="text"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder="Type your message..."
      />
      <button onClick={handleSend}>Send</button>
      <br />
      {aiData && (
        <>
          <h2>AI Response</h2>
          <p>{aiData.result}</p>
          <br />
        </>
      )}
      <button onClick={generatePdf}>Export as PDF</button>
    </div>
  );
}